from pathlib import Path
import sys


WORD_PAGE = Path("word_page.py")
EXCEL_PAGE = Path("excel_page.py")
EXCEL_TOOLS = Path("excel_tools.py")
NO_WHEEL = Path("no_wheel_combo.py")


def fail(message):
    print(f"\nERROR: {message}\n")
    sys.exit(1)


for required in [WORD_PAGE, EXCEL_PAGE, EXCEL_TOOLS]:
    if not required.exists():
        fail(f"{required.name} was not found.")

# Patch Word dropdowns so mouse-wheel page scrolling
# cannot accidentally change their values.
word_text = WORD_PAGE.read_text(encoding="utf-8")

if "from no_wheel_combo import NoWheelComboBox" not in word_text:
    import_anchor = "from global_hotkeys import GlobalReplacementHotkeys\n"

    if import_anchor not in word_text:
        fail("Could not locate the Word hotkey import.")

    word_text = word_text.replace(
        import_anchor,
        import_anchor
        + "from no_wheel_combo import NoWheelComboBox\n",
        1,
    )

word_text = word_text.replace(
    "QComboBox()",
    "NoWheelComboBox()",
)

WORD_PAGE.write_text(
    word_text,
    encoding="utf-8",
)

NO_WHEEL.write_text(
    'from PySide6.QtWidgets import QComboBox\n\n\nclass NoWheelComboBox(QComboBox):\n    def wheelEvent(self, event):\n        if self.view().isVisible():\n            super().wheelEvent(event)\n        else:\n            event.ignore()\n',
    encoding="utf-8",
)

EXCEL_PAGE.write_text(
    'from PySide6.QtCore import Qt\nfrom PySide6.QtWidgets import (\n    QFrame,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QPushButton,\n    QScrollArea,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom excel_tools import (\n    apply_date_format,\n    apply_text_cleanup,\n    refresh_open_workbooks,\n    refresh_worksheets,\n)\nfrom no_wheel_combo import NoWheelComboBox\n\n\nclass ExcelPage(QWidget):\n    def __init__(self):\n        super().__init__()\n\n        self.workbook_dropdown = NoWheelComboBox()\n        self.worksheet_dropdown = NoWheelComboBox()\n\n        outer_layout = QVBoxLayout(self)\n        outer_layout.setContentsMargins(0, 0, 0, 0)\n        outer_layout.setSpacing(0)\n\n        scroll_area = QScrollArea()\n        scroll_area.setWidgetResizable(True)\n        scroll_area.setFrameShape(QFrame.Shape.NoFrame)\n        scroll_area.setHorizontalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAlwaysOff\n        )\n\n        content = QWidget()\n        content.setObjectName("contentPage")\n\n        layout = QVBoxLayout(content)\n        layout.setContentsMargins(42, 36, 42, 36)\n        layout.setSpacing(18)\n\n        title = QLabel("Excel Tools")\n        title.setObjectName("pageTitle")\n\n        description = QLabel(\n            "Choose an open workbook and worksheet, "\n            "then apply a tool."\n        )\n        description.setObjectName("description")\n        description.setWordWrap(True)\n\n        layout.addWidget(title)\n        layout.addWidget(description)\n        layout.addSpacing(8)\n        layout.addWidget(self._create_workbook_card())\n        layout.addWidget(self._create_date_format_card())\n        layout.addWidget(self._create_text_cleanup_card())\n        layout.addStretch()\n\n        scroll_area.setWidget(content)\n        outer_layout.addWidget(scroll_area)\n\n        self.workbook_dropdown.currentIndexChanged.connect(\n            self._workbook_changed\n        )\n\n        refresh_open_workbooks(\n            self.workbook_dropdown,\n            self.worksheet_dropdown,\n            self,\n            show_warning=False,\n        )\n\n    def _create_workbook_card(self):\n        card = QFrame()\n        card.setObjectName("card")\n        card.setMaximumWidth(700)\n        card.setMinimumHeight(245)\n\n        layout = QVBoxLayout(card)\n        layout.setContentsMargins(24, 22, 24, 22)\n        layout.setSpacing(12)\n\n        title = QLabel("Open Excel workbook")\n        title.setObjectName("cardTitle")\n\n        text = QLabel(\n            "ToolPy only applies Excel tools to the workbook "\n            "and worksheet selected below."\n        )\n        text.setObjectName("cardText")\n        text.setWordWrap(True)\n\n        workbook_label = QLabel("Workbook")\n        workbook_label.setObjectName("cardText")\n\n        workbook_row = QHBoxLayout()\n        workbook_row.setSpacing(10)\n\n        self.workbook_dropdown.addItem(\n            "Choose an open Excel workbook",\n            "",\n        )\n        self.workbook_dropdown.setMinimumHeight(42)\n\n        refresh_button = QPushButton("Refresh")\n        refresh_button.setObjectName("secondaryButton")\n        refresh_button.setCursor(\n            Qt.CursorShape.PointingHandCursor\n        )\n        refresh_button.setMinimumHeight(42)\n        refresh_button.setFixedWidth(110)\n        refresh_button.clicked.connect(\n            lambda: refresh_open_workbooks(\n                self.workbook_dropdown,\n                self.worksheet_dropdown,\n                self,\n                show_warning=True,\n            )\n        )\n\n        workbook_row.addWidget(\n            self.workbook_dropdown,\n            1,\n        )\n        workbook_row.addWidget(refresh_button)\n\n        worksheet_label = QLabel("Worksheet")\n        worksheet_label.setObjectName("cardText")\n\n        self.worksheet_dropdown.addItem(\n            "Choose a worksheet",\n            "",\n        )\n        self.worksheet_dropdown.setMinimumHeight(42)\n\n        layout.addWidget(title)\n        layout.addWidget(text)\n        layout.addWidget(workbook_label)\n        layout.addLayout(workbook_row)\n        layout.addWidget(worksheet_label)\n        layout.addWidget(self.worksheet_dropdown)\n\n        return card\n\n    def _create_date_format_card(self):\n        card = QFrame()\n        card.setObjectName("card")\n        card.setMaximumWidth(700)\n        card.setMinimumHeight(430)\n\n        layout = QVBoxLayout(card)\n        layout.setContentsMargins(24, 22, 24, 22)\n        layout.setSpacing(12)\n\n        title = QLabel("Date Format")\n        title.setObjectName("cardTitle")\n\n        text = QLabel(\n            "Enter the first date cell. ToolPy reads downward in "\n            "that column and stops at the first blank cell."\n        )\n        text.setObjectName("cardText")\n        text.setWordWrap(True)\n\n        start_cell_label = QLabel("Start cell")\n        start_cell_label.setObjectName("cardText")\n\n        self.start_cell_input = QLineEdit("A2")\n        self.start_cell_input.setPlaceholderText("Example: A2")\n        self.start_cell_input.setMinimumHeight(42)\n        self.start_cell_input.setMaxLength(8)\n\n        order_label = QLabel("Date order")\n        order_label.setObjectName("cardText")\n\n        self.date_order_dropdown = NoWheelComboBox()\n        self.date_order_dropdown.addItems(\n            [\n                "Auto Detect",\n                "MM/DD/YYYY",\n                "DD/MM/YYYY",\n            ]\n        )\n        self.date_order_dropdown.setMinimumHeight(42)\n\n        output_label = QLabel("Output format")\n        output_label.setObjectName("cardText")\n\n        self.output_format_dropdown = NoWheelComboBox()\n        self.output_format_dropdown.addItems(\n            [\n                "MM/DD/YYYY",\n                "DD/MM/YYYY",\n                "Month DD, YYYY",\n                "MMM DD, YYYY",\n                "YYYY-MM-DD",\n            ]\n        )\n        self.output_format_dropdown.setMinimumHeight(42)\n\n        alignment_label = QLabel("Alignment")\n        alignment_label.setObjectName("cardText")\n\n        self.date_alignment_dropdown = NoWheelComboBox()\n        self.date_alignment_dropdown.addItems(\n            [\n                "No Change",\n                "Left",\n                "Center",\n                "Right",\n            ]\n        )\n        self.date_alignment_dropdown.setMinimumHeight(42)\n\n        apply_button = QPushButton("Apply")\n        apply_button.setObjectName("actionButton")\n        apply_button.setCursor(\n            Qt.CursorShape.PointingHandCursor\n        )\n        apply_button.setFixedSize(135, 44)\n        apply_button.clicked.connect(\n            self._apply_date_format\n        )\n\n        layout.addWidget(title)\n        layout.addWidget(text)\n        layout.addWidget(start_cell_label)\n        layout.addWidget(self.start_cell_input)\n        layout.addWidget(order_label)\n        layout.addWidget(self.date_order_dropdown)\n        layout.addWidget(output_label)\n        layout.addWidget(self.output_format_dropdown)\n        layout.addWidget(alignment_label)\n        layout.addWidget(self.date_alignment_dropdown)\n        layout.addSpacing(8)\n        layout.addWidget(\n            apply_button,\n            alignment=Qt.AlignmentFlag.AlignLeft,\n        )\n\n        return card\n\n    def _create_text_cleanup_card(self):\n        card = QFrame()\n        card.setObjectName("card")\n        card.setMaximumWidth(700)\n        card.setMinimumHeight(340)\n\n        layout = QVBoxLayout(card)\n        layout.setContentsMargins(24, 22, 24, 22)\n        layout.setSpacing(12)\n\n        title = QLabel("Text Cleanup")\n        title.setObjectName("cardTitle")\n\n        text = QLabel(\n            "Enter the first text cell. ToolPy cleans downward in "\n            "that column and stops at the first blank cell."\n        )\n        text.setObjectName("cardText")\n        text.setWordWrap(True)\n\n        start_cell_label = QLabel("Start cell")\n        start_cell_label.setObjectName("cardText")\n\n        self.text_start_cell_input = QLineEdit("A2")\n        self.text_start_cell_input.setPlaceholderText("Example: A2")\n        self.text_start_cell_input.setMinimumHeight(42)\n        self.text_start_cell_input.setMaxLength(8)\n\n        action_label = QLabel("Action")\n        action_label.setObjectName("cardText")\n\n        self.text_action_dropdown = NoWheelComboBox()\n        self.text_action_dropdown.addItems(\n            [\n                "Trim Spaces",\n                "Proper Case",\n                "UPPERCASE",\n                "lowercase",\n                "Sentence case",\n            ]\n        )\n        self.text_action_dropdown.setMinimumHeight(42)\n\n        alignment_label = QLabel("Alignment")\n        alignment_label.setObjectName("cardText")\n\n        self.text_alignment_dropdown = NoWheelComboBox()\n        self.text_alignment_dropdown.addItems(\n            [\n                "No Change",\n                "Left",\n                "Center",\n                "Right",\n            ]\n        )\n        self.text_alignment_dropdown.setMinimumHeight(42)\n\n        apply_button = QPushButton("Apply")\n        apply_button.setObjectName("actionButton")\n        apply_button.setCursor(\n            Qt.CursorShape.PointingHandCursor\n        )\n        apply_button.setFixedSize(135, 44)\n        apply_button.clicked.connect(\n            self._apply_text_cleanup\n        )\n\n        layout.addWidget(title)\n        layout.addWidget(text)\n        layout.addWidget(start_cell_label)\n        layout.addWidget(self.text_start_cell_input)\n        layout.addWidget(action_label)\n        layout.addWidget(self.text_action_dropdown)\n        layout.addWidget(alignment_label)\n        layout.addWidget(self.text_alignment_dropdown)\n        layout.addSpacing(8)\n        layout.addWidget(\n            apply_button,\n            alignment=Qt.AlignmentFlag.AlignLeft,\n        )\n\n        return card\n\n    def _workbook_changed(self):\n        refresh_worksheets(\n            self.workbook_dropdown,\n            self.worksheet_dropdown,\n            self,\n            show_warning=False,\n        )\n\n    def _apply_date_format(self):\n        apply_date_format(\n            self,\n            self.workbook_dropdown,\n            self.worksheet_dropdown,\n            self.start_cell_input.text(),\n            self.date_order_dropdown.currentText(),\n            self.output_format_dropdown.currentText(),\n            self.date_alignment_dropdown.currentText(),\n        )\n\n    def _apply_text_cleanup(self):\n        apply_text_cleanup(\n            self,\n            self.workbook_dropdown,\n            self.worksheet_dropdown,\n            self.text_start_cell_input.text(),\n            self.text_action_dropdown.currentText(),\n            self.text_alignment_dropdown.currentText(),\n        )\n',
    encoding="utf-8",
)

EXCEL_TOOLS.write_text(
    'import re\nfrom datetime import date, datetime, timedelta\n\nimport pywintypes\nimport win32com.client\nfrom PySide6.QtWidgets import QMessageBox\n\n\nMONTH_FORMATS = [\n    "%B %d, %Y",\n    "%B %d %Y",\n    "%b %d, %Y",\n    "%b %d %Y",\n    "%d %B %Y",\n    "%d %b %Y",\n    "%B %d, %y",\n    "%B %d %y",\n    "%b %d, %y",\n    "%b %d %y",\n    "%d %B %y",\n    "%d %b %y",\n]\n\nOUTPUT_FORMATS = {\n    "MM/DD/YYYY": "mm/dd/yyyy",\n    "DD/MM/YYYY": "dd/mm/yyyy",\n    "Month DD, YYYY": "mmmm dd, yyyy",\n    "MMM DD, YYYY": "mmm dd, yyyy",\n    "YYYY-MM-DD": "yyyy-mm-dd",\n}\n\nALIGNMENTS = {\n    "Left": -4131,\n    "Center": -4108,\n    "Right": -4152,\n}\n\n\ndef _get_excel():\n    return win32com.client.GetActiveObject(\n        "Excel.Application"\n    )\n\n\ndef _find_workbook(excel, workbook_name):\n    for workbook in excel.Workbooks:\n        if workbook.Name == workbook_name:\n            return workbook\n    return None\n\n\ndef _find_worksheet(workbook, worksheet_name):\n    for worksheet in workbook.Worksheets:\n        if worksheet.Name == worksheet_name:\n            return worksheet\n    return None\n\n\ndef _validate_target(\n    parent,\n    workbook_dropdown,\n    worksheet_dropdown,\n    start_cell_text,\n):\n    workbook_name = workbook_dropdown.currentData()\n    worksheet_name = worksheet_dropdown.currentData()\n    start_cell_text = start_cell_text.strip().upper()\n\n    if not workbook_name:\n        QMessageBox.warning(\n            parent,\n            "No Workbook Selected",\n            "Choose an open Excel workbook first.",\n        )\n        return None\n\n    if not worksheet_name:\n        QMessageBox.warning(\n            parent,\n            "No Worksheet Selected",\n            "Choose a worksheet first.",\n        )\n        return None\n\n    if not re.fullmatch(\n        r"\\$?[A-Z]{1,3}\\$?[1-9]\\d*",\n        start_cell_text,\n    ):\n        QMessageBox.warning(\n            parent,\n            "Invalid Start Cell",\n            "Enter a valid cell address such as A2, E2, or J12.",\n        )\n        return None\n\n    try:\n        excel = _get_excel()\n        workbook = _find_workbook(excel, workbook_name)\n\n        if workbook is None:\n            QMessageBox.warning(\n                parent,\n                "Workbook Not Found",\n                "The selected workbook is no longer open. Click Refresh.",\n            )\n            return None\n\n        worksheet = _find_worksheet(\n            workbook,\n            worksheet_name,\n        )\n\n        if worksheet is None:\n            QMessageBox.warning(\n                parent,\n                "Worksheet Not Found",\n                "The selected worksheet no longer exists. Click Refresh.",\n            )\n            return None\n\n        workbook.Activate()\n        worksheet.Activate()\n\n        start_cell = worksheet.Range(start_cell_text)\n\n        return (\n            workbook,\n            worksheet,\n            start_cell,\n            start_cell_text,\n        )\n\n    except Exception as error:\n        QMessageBox.critical(\n            parent,\n            "Excel Error",\n            "ToolPy could not access the selected Excel location.\\n\\n"\n            f"Error:\\n{error}",\n        )\n        return None\n\n\ndef _collect_downward_cells(worksheet, start_cell):\n    cells = []\n    row = start_cell.Row\n    column = start_cell.Column\n\n    while True:\n        cell = worksheet.Cells(row, column)\n        value = cell.Value\n\n        if value is None or str(value).strip() == "":\n            break\n\n        cells.append(cell)\n        row += 1\n\n    return cells\n\n\ndef _apply_alignment(cell, alignment):\n    if alignment == "No Change":\n        return\n\n    cell.HorizontalAlignment = ALIGNMENTS[alignment]\n\n\ndef refresh_open_workbooks(\n    workbook_dropdown,\n    worksheet_dropdown,\n    parent,\n    show_warning=True,\n):\n    current_workbook = workbook_dropdown.currentData()\n\n    workbook_dropdown.blockSignals(True)\n    workbook_dropdown.clear()\n    workbook_dropdown.addItem(\n        "Choose an open Excel workbook",\n        "",\n    )\n\n    try:\n        excel = _get_excel()\n        names = [\n            workbook.Name\n            for workbook in excel.Workbooks\n        ]\n\n        for name in names:\n            workbook_dropdown.addItem(name, name)\n\n        if current_workbook:\n            index = workbook_dropdown.findData(\n                current_workbook\n            )\n            if index >= 0:\n                workbook_dropdown.setCurrentIndex(index)\n\n        if show_warning and not names:\n            QMessageBox.warning(\n                parent,\n                "No Excel Workbooks",\n                "Open at least one workbook in Microsoft Excel.",\n            )\n\n    except Exception:\n        if show_warning:\n            QMessageBox.warning(\n                parent,\n                "Excel Not Found",\n                "Open Microsoft Excel and at least one workbook.",\n            )\n\n    finally:\n        workbook_dropdown.blockSignals(False)\n\n    refresh_worksheets(\n        workbook_dropdown,\n        worksheet_dropdown,\n        parent,\n        show_warning=False,\n    )\n\n\ndef refresh_worksheets(\n    workbook_dropdown,\n    worksheet_dropdown,\n    parent,\n    show_warning=True,\n):\n    current_sheet = worksheet_dropdown.currentData()\n    workbook_name = workbook_dropdown.currentData()\n\n    worksheet_dropdown.blockSignals(True)\n    worksheet_dropdown.clear()\n    worksheet_dropdown.addItem(\n        "Choose a worksheet",\n        "",\n    )\n\n    try:\n        if not workbook_name:\n            return\n\n        excel = _get_excel()\n        workbook = _find_workbook(\n            excel,\n            workbook_name,\n        )\n\n        if workbook is None:\n            if show_warning:\n                QMessageBox.warning(\n                    parent,\n                    "Workbook Not Found",\n                    "The selected workbook is no longer open.",\n                )\n            return\n\n        for worksheet in workbook.Worksheets:\n            worksheet_dropdown.addItem(\n                worksheet.Name,\n                worksheet.Name,\n            )\n\n        if current_sheet:\n            index = worksheet_dropdown.findData(\n                current_sheet\n            )\n            if index >= 0:\n                worksheet_dropdown.setCurrentIndex(index)\n\n    except Exception as error:\n        if show_warning:\n            QMessageBox.warning(\n                parent,\n                "Worksheet Error",\n                "ToolPy could not list the worksheets.\\n\\n"\n                f"Error:\\n{error}",\n            )\n\n    finally:\n        worksheet_dropdown.blockSignals(False)\n\n\ndef apply_date_format(\n    parent,\n    workbook_dropdown,\n    worksheet_dropdown,\n    start_cell_text,\n    date_order,\n    output_format,\n    alignment,\n):\n    target = _validate_target(\n        parent,\n        workbook_dropdown,\n        worksheet_dropdown,\n        start_cell_text,\n    )\n\n    if target is None:\n        return\n\n    _workbook, worksheet, start_cell, address = target\n    cells = _collect_downward_cells(\n        worksheet,\n        start_cell,\n    )\n\n    if not cells:\n        QMessageBox.warning(\n            parent,\n            "No Dates Found",\n            f"{address} is empty.",\n        )\n        return\n\n    try:\n        detected_order = date_order\n\n        if date_order == "Auto Detect":\n            detected_order = _detect_numeric_order(cells)\n\n        number_format = OUTPUT_FORMATS[output_format]\n\n        for cell in cells:\n            parsed, _was_real_date = _parse_value(\n                cell.Value,\n                detected_order,\n            )\n\n            if parsed is None:\n                continue\n\n            cell.Value = parsed\n            cell.NumberFormat = number_format\n            _apply_alignment(cell, alignment)\n\n    except Exception as error:\n        QMessageBox.critical(\n            parent,\n            "Date Format Error",\n            "ToolPy could not format the dates.\\n\\n"\n            f"Error:\\n{error}",\n        )\n\n\ndef apply_text_cleanup(\n    parent,\n    workbook_dropdown,\n    worksheet_dropdown,\n    start_cell_text,\n    action,\n    alignment,\n):\n    target = _validate_target(\n        parent,\n        workbook_dropdown,\n        worksheet_dropdown,\n        start_cell_text,\n    )\n\n    if target is None:\n        return\n\n    _workbook, worksheet, start_cell, address = target\n    cells = _collect_downward_cells(\n        worksheet,\n        start_cell,\n    )\n\n    if not cells:\n        QMessageBox.warning(\n            parent,\n            "No Text Found",\n            f"{address} is empty.",\n        )\n        return\n\n    try:\n        for cell in cells:\n            value = cell.Value\n\n            if value is None:\n                continue\n\n            text = str(value)\n\n            if action == "Trim Spaces":\n                cleaned = " ".join(text.split())\n            elif action == "Proper Case":\n                cleaned = " ".join(text.split()).title()\n            elif action == "UPPERCASE":\n                cleaned = " ".join(text.split()).upper()\n            elif action == "lowercase":\n                cleaned = " ".join(text.split()).lower()\n            elif action == "Sentence case":\n                normalized = " ".join(text.split())\n                cleaned = (\n                    normalized[:1].upper()\n                    + normalized[1:].lower()\n                    if normalized\n                    else normalized\n                )\n            else:\n                cleaned = text\n\n            cell.Value = cleaned\n            _apply_alignment(cell, alignment)\n\n    except Exception as error:\n        QMessageBox.critical(\n            parent,\n            "Text Cleanup Error",\n            "ToolPy could not clean the text.\\n\\n"\n            f"Error:\\n{error}",\n        )\n\n\ndef _detect_numeric_order(cells):\n    mm_dd_evidence = 0\n    dd_mm_evidence = 0\n\n    for cell in cells:\n        value = cell.Value\n\n        if _is_real_excel_date(value):\n            continue\n\n        parts = _numeric_parts(str(value))\n\n        if parts is None:\n            continue\n\n        first, second, _year = parts\n\n        if first > 12 and second <= 12:\n            dd_mm_evidence += 1\n        elif second > 12 and first <= 12:\n            mm_dd_evidence += 1\n\n    if dd_mm_evidence > mm_dd_evidence:\n        return "DD/MM/YYYY"\n\n    return "MM/DD/YYYY"\n\n\ndef _is_real_excel_date(value):\n    return isinstance(\n        value,\n        (\n            datetime,\n            date,\n            pywintypes.TimeType,\n        ),\n    )\n\n\ndef _parse_value(value, numeric_order):\n    if isinstance(value, pywintypes.TimeType):\n        return datetime(\n            value.year,\n            value.month,\n            value.day,\n            value.hour,\n            value.minute,\n            value.second,\n        ), True\n\n    if isinstance(value, datetime):\n        return value, True\n\n    if isinstance(value, date):\n        return datetime(\n            value.year,\n            value.month,\n            value.day,\n        ), True\n\n    if isinstance(value, (int, float)) and 1 <= float(value) <= 2958465:\n        excel_epoch = datetime(1899, 12, 30)\n\n        try:\n            return excel_epoch + timedelta(\n                days=float(value)\n            ), True\n        except (OverflowError, ValueError):\n            return None, False\n\n    text = str(value).strip()\n\n    if not text:\n        return None, False\n\n    month_name_date = _parse_month_name(text)\n\n    if month_name_date is not None:\n        return month_name_date, False\n\n    iso_date = _parse_iso_date(text)\n\n    if iso_date is not None:\n        return iso_date, False\n\n    parts = _numeric_parts(text)\n\n    if parts is None:\n        return None, False\n\n    first, second, year = parts\n\n    if year < 100:\n        year += 2000 if year < 70 else 1900\n\n    try:\n        if first > 12 and second <= 12:\n            day = first\n            month = second\n        elif second > 12 and first <= 12:\n            month = first\n            day = second\n        elif numeric_order == "DD/MM/YYYY":\n            day = first\n            month = second\n        else:\n            month = first\n            day = second\n\n        return datetime(year, month, day), False\n\n    except ValueError:\n        return None, False\n\n\ndef _parse_month_name(text):\n    normalized = re.sub(\n        r"\\s+",\n        " ",\n        text.replace(".", "").strip(),\n    )\n\n    for pattern in MONTH_FORMATS:\n        try:\n            return datetime.strptime(\n                normalized,\n                pattern,\n            )\n        except ValueError:\n            continue\n\n    return None\n\n\ndef _parse_iso_date(text):\n    try:\n        return datetime.strptime(\n            text,\n            "%Y-%m-%d",\n        )\n    except ValueError:\n        return None\n\n\ndef _numeric_parts(text):\n    match = re.fullmatch(\n        r"\\s*(\\d{1,2})[\\/\\-.](\\d{1,2})[\\/\\-.](\\d{2,4})\\s*",\n        text,\n    )\n\n    if match is None:\n        return None\n\n    return tuple(\n        int(part)\n        for part in match.groups()\n    )\n',
    encoding="utf-8",
)

